Here's the airport transfer, right below the flight: metro route, step by step, compared with a taxi and a pre-booked car.

```svelte file=lib/AirportTransfer.svelte
<script>
  import { Section, Action, List, ListRow, Table } from 'design';
  import Train from 'phosphor-svelte/lib/Train';
  import Car from 'phosphor-svelte/lib/Car';

  let saved = $state(false);
  let carBooked = $state(false);

  const steps = [
    { label: 'Aeroporto station', sub: 'Through arrivals with cabin bag only, buy a card and single ticket', time: '10:15' },
    { label: 'Red line to Alameda', sub: 'Direction São Sebastião', time: '10:20' },
    { label: 'Green line to Martim Moniz', sub: 'Change at Alameda, direction Cais do Sodré', time: '10:35' },
    { label: 'Walk up to Casa Lumeira', sub: 'About 10 min, or Tram 28 and the 5-minute walk', time: '10:45' },
    { label: 'Drop bags at Casa Lumeira', sub: 'Bags held from 10:30', time: '10:55' }
  ];

  const columns = ['Option', 'Time', 'Cost'];
  const rows = [
    ['Metro, Red then Green line', 'About 30 min + walk', 'About €2'],
    ['Taxi from the arrivals rank', 'About 20 min', '€15–20'],
    ['Rotalis pre-booked car', 'About 20 min', '€32']
  ];
</script>

<Section title="Airport Transfer" kicker="Fri Nov 13 · Lisbon airport → Alfama">
  <List>
    {#each steps as step, i}
      <ListRow index={i + 1} label={step.label} sub={step.sub} trailing={step.time} />
    {/each}
  </List>
  <Table {columns} {rows} pick={0} />
  <p class="m-meta">Metro is quickest to sort and cheapest; the car meets you at arrivals with a name sign.</p>
  {#snippet actions()}
    <Action
      label={saved ? 'Route saved' : 'Save metro route'}
      sublabel={saved ? 'Red line, then Green line' : 'Leaves about 10:20'}
      icon={Train}
      primary={!saved}
      disabled={saved}
      onclick={() => (saved = true)}
    />
    <Action
      label={carBooked ? 'Car booked' : 'Book a car'}
      sublabel={carBooked ? 'Rotalis · Fri 09:55 arrival' : '€32 · meets you at arrivals'}
      icon={Car}
      disabled={carBooked}
      onclick={() => (carBooked = true)}
    />
  {/snippet}
</Section>
```

